canales = {}

def suscribir(canal, nombre):
    canales.setdefault(canal, []).append(nombre)

def publicar(canal, mensaje):
    suscriptores = canales.get(canal, [])
    for s in suscriptores:
        print(f"{s} recibe en {canal}: {mensaje}")
    return len(suscriptores)

suscribir("noticias.deportes", "app_movil")
suscribir("noticias.deportes", "panel_web")
entregados = publicar("noticias.deportes", "Gol en el minuto 90")
print(f"Entregado a {entregados} suscriptores")

sin_oyentes = publicar("noticias.clima", "Alerta de tormenta")
print(f"Entregado a {sin_oyentes} suscriptores")
